input.content:
packer {
  required_plugins {
    googlecompute = {
      source  = "github.com/hashicorp/googlecompute"
      version = ">= 1.1.0"
    }
  }
}

variable "project_id" {
  type    = string
  default = "prod-apps-454414"
}

variable "vllm_version" {
  type    = string
  default = "v0.8.5"
}

variable "zone" {
  type    = string
  default = "us-east1-b"
}

source "googlecompute" "vllm" {
  project_id              = var.project_id
  source_image_project_id = ["rocky-linux-accelerator-cloud"]
  source_image_family     = "rocky-linux-9-optimized-gcp-nvidia-580"
  zone                    = var.zone
  machine_type            = "n1-standard-4"
  image_name              = "vllm-${replace(var.vllm_version, ".", "-")}-{{timestamp}}"
  image_family            = "vllm-prod"
  image_description       = "Rocky 9 + NVIDIA 580 + Docker + nvidia-container-toolkit + vllm/vllm-openai:${var.vllm_version} pre-pulled"

  ssh_username = "packer"
  disk_size    = 50
  disk_type    = "pd-ssd"

  labels = {
    managed-by     = "packer"
    iac-repository = "infrastructure"
    service        = "vllm"
    vllm-version   = replace(var.vllm_version, ".", "-")
  }
}

build {
  sources = ["source.googlecompute.vllm"]

  provisioner "shell" {
    inline = [
      "echo 'Waiting for cloud-init...'",
      "sudo cloud-init status --wait || true",
    ]
  }

  provisioner "file" {
    source      = "${path.root}/files/prebuild.sh"
    destination = "/tmp/prebuild.sh"
  }

  provisioner "shell" {
    inline = [
      "chmod +x /tmp/prebuild.sh",
      "sudo VLLM_VERSION=${var.vllm_version} /tmp/prebuild.sh",
    ]
  }
}

